183	// 所有字段都必须明确提交且合法，不使用任何默认值。
184	func validateConfig(cfg roomConfig) (int, string, bool) {
185		name := strings.TrimSpace(cfg.Name)
186		if name == "" {
187			return http.StatusBadRequest, "房间名称不能为空", false
188		}
189		if len([]rune(name)) > 40 {
190			return http.StatusBadRequest, "房间名称去掉首尾空白后不能超过 40 个字符", false
191		}
192	
193		switch cfg.Game {
194		case "gomoku":
195			if cfg.Capacity != 2 {
196				return http.StatusBadRequest, "五子棋的人数上限固定为 2 人", false
197			}
198		case "ludo":
199			if cfg.Capacity < 2 || cfg.Capacity > 4 {
200				return http.StatusBadRequest, "飞行棋的人数上限必须为 2 至 4 人", false
201			}
202		default:
203			return http.StatusBadRequest, "未知游戏规则，目前仅支持 gomoku（五子棋）和 ludo（飞行棋）", false
204		}
205	
206		if cfg.TurnSeconds != 0 && (cfg.TurnSeconds < 10 || cfg.TurnSeconds > 600) {
207			return http.StatusBadRequest, "每步时间限制只能为 0（不限时）或 10 至 600 秒之间的整数", false
208		}
209		return 0, "", true
210	}
